import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { Container, AppBar, Toolbar, Typography, Button } from '@mui/material';
import DashboardPage from './pages/DashboardPage';
import FlakyTestsPage from './pages/FlakyTestsPage';
import FailureTrendsPage from './pages/FailureTrendsPage';
import RootCausePage from './pages/RootCausePage';
import WeeklyDigestPage from './pages/WeeklyDigestPage';

function App() {
  return (
    <Router>
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            Intelligent Test Report Analyzer
          </Typography>
          <Button color="inherit" component={Link} to="/">Dashboard</Button>
          <Button color="inherit" component={Link} to="/flaky-tests">Flaky Tests</Button>
          <Button color="inherit" component={Link} to="/failure-trends">Failure Trends</Button>
          <Button color="inherit" component={Link} to="/root-cause">Root Cause</Button>
          <Button color="inherit" component={Link} to="/weekly-digest">Weekly Digest</Button>
        </Toolbar>
      </AppBar>
      <Container sx={{ marginTop: 4 }}>
        <Routes>
          <Route path="/" element={<DashboardPage />} />
          <Route path="/flaky-tests" element={<FlakyTestsPage />} />
          <Route path="/failure-trends" element={<FailureTrendsPage />} />
          <Route path="/root-cause" element={<RootCausePage />} />
          <Route path="/weekly-digest" element={<WeeklyDigestPage />} />
        </Routes>
      </Container>
    </Router>
  );
}

export default App;
